import test from 'node:test';
import assert from 'node:assert/strict';
import {dateKey,nextWeek,range,addDays} from '../core.js';
class Element {constructor(){this.innerHTML='';this.value='';this.style={};this.dataset={};this.listeners={};this.textContent='';this.attributes={};this.classList={toggle(){}};}addEventListener(event,fn){this.listeners[event]=fn;}querySelectorAll(selector){if(!/^\[data-(?:(?:edit|delete)-usual|meal-mode|training-day|import-step|gap-meal)\]$/.test(selector))return [];const key=selector.slice(1,-1);this.rows??=new Map();return [...this.innerHTML.matchAll(new RegExp(key+'="([^"]+)"','g'))].map(m=>{const id=key+'-'+m[1];if(!this.rows.has(id))this.rows.set(id,new Element());const row=this.rows.get(id);const attr=key.slice(5).replace(/-([a-z])/g,(_,c)=>c.toUpperCase());row.dataset[attr]=m[1];return row;});}setAttribute(key,value){this.attributes[key]=value;}querySelector(){return new Element();}showModal(){this.open=true;}close(){this.open=false;}focus(){}select(){}click(){} append(el){this.lastChild=el;}}
const elems=new Map();global.document={body:{classList:{toggle(){}}},querySelector:s=>{if(!elems.has(s))elems.set(s,new Element());const el=elems.get(s);if(s==='#meal-form')el.innerHTML=elems.get('#modal')?.innerHTML||'';return el;},createElement:()=>new Element()};
const memory=new Map();global.localStorage={getItem:k=>memory.get(k),setItem:(k,v)=>memory.set(k,v)};
global.window={addEventListener(){},scrollTo(){}};global.matchMedia=()=>({matches:false,addEventListener(){}});global.FormData=class {constructor(form){this.items=Object.entries(form.values||{});}[Symbol.iterator](){return this.items[Symbol.iterator]();}get(k){return this.getAll(k)[0]??null;}getAll(k){return this.items.filter(([key])=>key===k).flatMap(([,v])=>Array.isArray(v)?v:[v]);} };
const storage=()=>JSON.parse(memory.get('fuel-and-flow-v1'));
const element=s=>document.querySelector(s);
async function click(dataset){await element('#app').listeners.click({target:{closest:()=>({dataset})}});}
await import('../app.js');
test('all app tabs render without runtime errors and user input is escaped',async()=>{for(const view of ['today','plan','foods','insights','coach','settings','more']){await click({action:'nav',view});assert.match(element('#app').innerHTML,/Fuel & Flow/);assert.ok(element('#app').innerHTML.length>4000);} });
test('check-in stores entered metrics without manufacturing food eaten',async()=>{await click({action:'nav',view:'today',panel:'checkin'});element('#checkin').onsubmit({preventDefault(){},target:{values:{energyBefore:'4',energyAfter:'6',sleep:'7.5',water:'96',weight:'160',bjjMinutes:'90',liftMinutes:'',notes:'<script>test</script>',recovery:'Okay'}}});const saved=storage();assert.equal(saved.days[dateKey()].energyBefore,4);assert.equal(saved.days[dateKey()].meals.length,0);assert.ok(!Object.hasOwn(saved.days[dateKey()]));assert.equal(saved.days[dateKey()].bjjMinutes,null);assert.equal(saved.days[dateKey()].notes,'');});
test('ChatGPT prompt generation, preview and confirmed import populate only plans',async()=>{const start=nextWeek();await click({action:'nav',view:'coach'});await click({action:'coach-mode',mode:'plan'});element('#coach-week').value=start;await click({action:'generate'});assert.match(element('#app').innerHTML,/schemaVersion/);const meal={name:'Yogurt & banana',portion:'170g yogurt + banana',time:'15:00',calories:210,protein:18,carbs:32,fat:1};await click({action:'coach-mode',mode:'import'});element('#import-week').value=start;element('#plan-input').value=JSON.stringify({schemaVersion:1,weekStart:start,days:range(start,'week').map(date=>({date,meals:[meal]}))});await click({action:'preview-import'});assert.match(element('#import-preview').innerHTML,/Seven days validated/);await click({action:'commit-import'});element('#confirm-action').onclick();assert.equal(Object.keys(storage().plans).length,7);assert.equal(storage().days[dateKey()].meals.length,0);assert.match(element('#app').innerHTML,/Yogurt &amp; banana/);});
test('log eaten requires confirmation and then populates the correct date',async()=>{const start=nextWeek();await click({action:'eat-plan',date:start,index:'0'});assert.equal(storage().days[start],undefined);element('#confirm-action').onclick();assert.equal(storage().days[start].meals.length,1);assert.equal(storage().days[start].meals[0].calories,210);assert.equal(storage().days[start].complete,false);});
