test('usual-food editor persists an edited entry and add meal supports week copies',async()=>{await click({action:'nav',view:'today'});await click({action:'add-meal'});assert.match(element('#modal').innerHTML,/Entire Monday–Sunday week/);assert.match(element('#modal').innerHTML,/Meal plan \(not eaten\)/);element('#meal-form').onsubmit({preventDefault(){},target:{values:{name:'Custom sandwich',portion:'PB & banana on sourdough',time:'15:00',date:dateKey(),calories:'400',protein:'14',carbs:'60',fat:'13',copyWeek:dateKey(),copyAll:'on',copyDestination:'plan',saveUsual:'on'}}});const s=storage();assert.ok(s.usualFoods.some(m=>m.name==='Custom sandwich'));const week=range(dateKey(),'week').filter(k=>k!==dateKey());for(const day of week)assert.ok(s.plans[day].meals.some(m=>m.name==='Custom sandwich'));assert.ok(s.days[dateKey()].meals.some(m=>m.name==='Custom sandwich'));await click({action:'favorites'});assert.match(element('#modal').innerHTML,/data-edit-usual/);assert.match(element('#modal').innerHTML,/data-delete-usual/);});
