test('weekly schedule editor exposes session controls and blue logo appears',async()=>{await click({action:'training-schedule'});assert.match(element('#modal').innerHTML,/data-add-training/);assert.match(element('#modal').innerHTML,/No sessions/);assert.match(element('#app').innerHTML,/icons\/logo.svg/);});
test('planned Delete requires confirmation and leaves logged meals intact',async()=>{const date=nextWeek(),before=storage();const mealCount=before.plans[date].meals.length,logged=before.days[date].meals;await click({action:'delete-planned-meal',date,index:'0'});assert.equal(storage().plans[date].meals.length,mealCount);assert.match(element('#modal').innerHTML,/Delete this planned meal/);element('#confirm-action').onclick();assert.equal(storage().plans[date].meals.length,mealCount-1);assert.deepEqual(storage().days[date].meals,logged);});
test('nutrition settings preview updates before save and invalid values do not persist',async()=>{await click({action:'nav',view:'settings',panel:'goals'});assert.match(element('#app').innerHTML,/BJJ Training Day Goals/);assert.match(element('#app').innerHTML,/Non-BJJ Day Goals/);const fields={'goal-bjj-calories':'2400','goal-bjj-protein':'180','goal-bjj-carbs':'250','goal-bjj-fat':'70','goal-nonBjj-calories':'2100','goal-nonBjj-protein':'150','goal-nonBjj-carbs':'180','goal-nonBjj-fat':'60'};const form=element('#settings');form.values=fields;form.listeners.input();assert.match(element('#weekly-nutrition-preview').innerHTML,/2,100/);assert.match(element('#macro-info-bjj').innerHTML,/2,350/);const before=storage();form.onsubmit({preventDefault(){},target:{values:{...fields,'goal-bjj-protein':'-1'}}});assert.deepEqual(storage(),before);form.onsubmit({preventDefault(){},target:{values:fields}});assert.equal(storage().nutritionGoals.bjj.calories,2400);assert.equal(storage().nutritionGoals.nonBjj.protein,150);await click({action:'nav',view:'today'});assert.match(element('#app').innerHTML,/Non-BJJ Day/);assert.match(element('#app').innerHTML,/2,100 kcal goal/);});
test('saved nutrition profiles and meals survive reopening the application',async()=>{const before=storage();await import('../app.js?nutrition-reopen');assert.deepEqual(storage().days,before.days);assert.deepEqual(storage().nutritionGoals,before.nutritionGoals);assert.match(element('#app').innerHTML,/2,100 kcal goal/);});
test('new feature controls stay within existing tabs, and recovery saves without altering food',async()=>{await click({action:'nav',view:'today',panel:'training'});assert.match(element('#app').innerHTML,/Training &amp; fuel timeline|Training & fuel timeline/);await click({action:'section',group:'today',panel:'checkin'});assert.match(element('#app').innerHTML,/name="sleepQuality"/);assert.match(element('#app').innerHTML,/name="stress"/);const before=storage().days[dateKey()].meals;element('#checkin').onsubmit({preventDefault(){},target:{values:{sleepQuality:'4',soreness:'2',stress:'3',notes:'Recovered well',recovery:'Good'}}});assert.deepEqual(storage().days[dateKey()].meals,before);assert.equal(storage().days[dateKey()].stress,3);const saved=storage();element('#checkin').onsubmit({preventDefault(){},target:{values:{stress:'6'}}});assert.deepEqual(storage(),saved);await click({action:'nav',view:'insights'});assert.match(element('#app').innerHTML,/Weekly recovery & nutrition review/);await click({action:'section',group:'insights',panel:'weight'});assert.match(element('#app').innerHTML,/rolling seven-day average/);await click({action:'nav',view:'settings',panel:'app'});assert.match(element('#app').innerHTML,/Application updates/);await click({action:'section',group:'settings',panel:'data'});assert.match(element('#app').innerHTML,/Backup reminder/);});
test('recipe editor saves batch nutrition, and shared meal editor scales and persists one serving',async()=>{await click({action:'recipes'});element('#new-recipe').onclick();const recipeForm=element('#recipe-form');recipeForm.values={name:'Oat batch',time:'08:30',servings:'4',notes:'Prepare ahead'};for(const ingredient of [{name:'oats',amount:2,unit:'cup',calories:600,protein:20,carbs:100,fat:12},{name:'milk',amount:4,unit:'cup',calories:400,protein:20,carbs:60,fat:12}]){for(const [key,value] of Object.entries(ingredient))element('#recipe-item-'+key).value=String(value);element('#recipe-add-ingredient').onclick();}recipeForm.onsubmit({preventDefault(){}});assert.equal(element('#recipe-error').textContent,'');assert.equal(element('#recipe-ingredient-error').textContent,'');assert.equal(storage().recipes[0].servings,4);assert.equal(storage().recipes[0].ingredients[0].amount,2);await click({action:'add-meal'});assert.match(element('#modal').innerHTML,/Fill from Recipes/);assert.match(element('#modal').innerHTML,/Serving multiplier/);const form=element('#meal-form');form.values={name:'Toast',time:'12:00',portion:'1 slice bread',date:dateKey(),calories:'100',protein:'4',carbs:'18',fat:'1',servings:'1',copyWeek:dateKey(),copyDestination:'plan'};form.elements={namedItem:key=>({get value(){return form.values[key]},set value(v){form.values[key]=String(v)}})};element('#meal-servings').value='1.5';form.values.servings='1.5';element('#meal-servings').oninput();assert.equal(form.values.calories,'150');assert.equal(form.values.protein,'6');form.onsubmit({preventDefault(){},target:form});const meal=storage().days[dateKey()].meals.find(m=>m.name==='Toast');assert.equal(meal.calories,150);assert.equal(meal.servingBase.calories,100);assert.equal(meal.servings,1.5);});
test('plan swap retains its original, preview shows new targets and eaten logs remain untouched',async()=>{const before=storage(),date=Object.keys(before.plans).find(k=>before.plans[k].meals.length),original=before.plans[date].meals[0],actual=before.days[date]?.meals||[];await click({action:'swap-plan',date,index:'0'});const form=element('#swap-form');form.values={choice:'0',servings:'1'};form.listeners.input();assert.match(element('#swap-preview').innerHTML,/After swap/);form.onsubmit({preventDefault(){}});assert.deepEqual(storage().days[date]?.meals||[],actual);assert.equal(storage().plans[date].meals[0].originalPlan.name,original.name);assert.equal(storage().plans[date].meals[0].id,original.id);await click({action:'toggle-skip-plan',date,index:'0'});assert.equal(storage().plans[date].meals[0].skipped,true);await click({action:'toggle-skip-plan',date,index:'0'});assert.equal(storage().plans[date].meals[0].skipped,false);});
test('pantry and reminder settings persist, restore offers a review before replacement',async()=>{await click({action:'pantry'});const pantry=element('#pantry-form');pantry.values={pantry:'Oats\nMilk\nOats'};pantry.onsubmit({preventDefault(){},target:pantry});assert.deepEqual(storage().pantry,['oats','milk']);await click({action:'nav',view:'settings',panel:'data'});element('#backup-reminder').onsubmit({preventDefault(){},target:{values:{reminderDays:'30'}}});assert.equal(storage().backupSettings.reminderDays,30);const before=storage();await element('#backup-file').onchange({target:{files:[{size:100,text:async()=>JSON.stringify(before)}]}});assert.match(element('#modal').innerHTML,/Review backup before restoring/);assert.match(element('#modal').innerHTML,/Logged meals/);assert.match(element('#modal').innerHTML,/Download current backup/);assert.deepEqual(storage(),before);});
test('usual food Edit and Delete actions update the library only, retaining existing meal logs',async()=>{await click({action:'favorites'});const before=storage(),food=before.usualFoods[0];assert.ok(food);const edit=element('#modal').querySelectorAll('[data-edit-usual]')[0];edit.onclick();assert.match(element('#modal').innerHTML,/Edit usual food/);element('#meal-form').onsubmit({preventDefault(){},target:{values:{name:'Updated sandwich',portion:'One custom serving',time:'14:30',calories:'450',protein:'16',carbs:'65',fat:'15',servings:'1'}}});assert.equal(storage().usualFoods[0].id,food.id);assert.equal(storage().usualFoods[0].name,'Updated sandwich');assert.equal(storage().usualFoods[0].calories,450);assert.deepEqual(storage().days,before.days);await click({action:'favorites'});const remove=element('#modal').querySelectorAll('[data-delete-usual]')[0];remove.onclick();assert.match(element('#modal').innerHTML,/Remove usual food/);assert.equal(storage().usualFoods.length,before.usualFoods.length);element('#confirm-action').onclick();assert.equal(storage().usualFoods.length,before.usualFoods.length-1);assert.deepEqual(storage().days,before.days);});
test('food lookup fills the meal editor only after review, preserves source metadata, and leaves previous logs untouched',async()=>{const originalFetch=global.fetch;global.fetch=async url=>{assert.match(url,/api\/v3\/product\/3017624010701/);return new Response(JSON.stringify({status:1,product:{code:'3017624010701',product_name:'Test yogurt',brands:'Test brand',serving_quantity:100,serving_quantity_unit:'g',nutriments:{'energy-kcal_100g':100,proteins_100g:10,carbohydrates_100g:12,fat_100g:2}}}));};try{await click({action:'add-meal'});assert.match(element('#modal').innerHTML,/Search foods \/ scan barcode/);const before=storage(),form=element('#meal-form');form.values={name:'',time:'12:00',portion:'',date:dateKey(),calories:'',protein:'',carbs:'',fat:'',servings:'1',copyWeek:dateKey(),copyDestination:'plan'};form.elements={namedItem:key=>({get value(){return form.values[key]},set value(v){form.values[key]=String(v)}})};element('#food-barcode').value='3017624010701';await element('#lookup-barcode').onclick();assert.match(element('#food-review').innerHTML,/Test yogurt/);assert.deepEqual(storage(),before);element('#food-amount').value='1';element('#food-unit').value='serving';element('#food-amount').oninput();assert.match(element('#food-macros').innerHTML,/value="100"/);for(const [k,v] of Object.entries({calories:'100',protein:'10',carbs:'12',fat:'2'}))element('#lookup-'+k).value=v;element('#use-food-result').onclick();assert.equal(form.values.calories,'100');assert.equal(form.values.name,'Test yogurt (Test brand)');assert.deepEqual({...storage(),savedFoods:before.savedFoods},before);assert.equal(storage().savedFoods.length,before.savedFoods.length+1);form.onsubmit({preventDefault(){},target:form});assert.equal(storage().days[dateKey()].meals.find(m=>m.name==='Test yogurt (Test brand)').foodSource.provider,'off');assert.equal(storage().days[dateKey()].meals.length,before.days[dateKey()].meals.length+1);assert.deepEqual(storage().days[dateKey()].meals.filter(m=>m.name!=='Test yogurt (Test brand)'),before.days[dateKey()].meals);}finally{global.fetch=originalFetch;}});
test('focused pages separate data and forms instead of rendering every feature at once',async()=>{await click({action:'nav',view:'today'});assert.match(element('#app').innerHTML,/data-panel="overview"/);assert.doesNotMatch(element('#app').innerHTML,/<form|id="checkin"|Training & fuel timeline/);assert.match(element('#app').innerHTML,/Energy Levels/);await click({action:'section',group:'today',panel:'checkin'});assert.match(element('#app').innerHTML,/id="checkin"/);assert.doesNotMatch(element('#app').innerHTML,/id="settings"|class="swipe-meal"/);await click({action:'nav',view:'plan',panel:'meals'});assert.doesNotMatch(element('#app').innerHTML,/grocery-card|Your weekly rhythm/);await click({action:'section',group:'plan',panel:'groceries'});assert.match(element('#app').innerHTML,/Grocery list/);assert.doesNotMatch(element('#app').innerHTML,/data-action="add-plan"/);await click({action:'nav',view:'settings',panel:'profile'});assert.match(element('#app').innerHTML,/name="sex"/);assert.doesNotMatch(element('#app').innerHTML,/goal-bjj|id="lookup-settings"|id="backup-reminder"/);await click({action:'section',group:'settings',panel:'goals'});assert.match(element('#app').innerHTML,/goal-bjj/);assert.doesNotMatch(element('#app').innerHTML,/name="preferences"|id="backup-reminder"/);await click({action:'nav',view:'coach',panel:'review'});assert.doesNotMatch(element('#app').innerHTML,/id="plan-input"/);await click({action:'coach-mode',mode:'import'});assert.match(element('#app').innerHTML,/id="plan-input"/);assert.doesNotMatch(element('#app').innerHTML,/id="review-date"/);});
