test('new meals default to current local time while existing meal times stay unchanged',async()=>{await click({action:'nav',view:'today',panel:'food'});const local=()=>{const n=new Date();return `${String(n.getHours()).padStart(2,'0')}:${String(n.getMinutes()).padStart(2,'0')}`;};const before=local();await click({action:'add-meal'});const value=element('#modal').innerHTML.match(/name="time"[^>]*value="([^"]+)"/)[1];assert.ok([before,local()].includes(value));const meal=storage().days[dateKey()].meals[0],saved=structuredClone(storage());await click({action:'edit-meal',id:meal.id});assert.match(element('#modal').innerHTML,new RegExp(`name="time"[^>]*value="${meal.time}"`));assert.deepEqual(storage(),saved);});
test('dedicated water tracker saves, edits and deletes drinks with overview and timeline totals',async()=>{await click({action:'nav',view:'today',panel:'hydration'});assert.match(element('#app').innerHTML,/Water & drinks/);for(const amount of [8,12,16,24,32])assert.match(element('#app').innerHTML,new RegExp(`data-drink-oz="${amount}"`));assert.doesNotMatch(element('#app').innerHTML,/data-drink-oz="4"/);const date=dateKey(),before=structuredClone(storage().days[date]),form=element('#drink-entry');form.values={type:'Gatorade',time:'15:30',ounces:'32',calories:'80',protein:'0',carbs:'20',fat:'0'};form.onsubmit({preventDefault(){}});let saved=storage().days[date],drink=saved.drinks.at(-1);assert.equal(drink.ounces,32);assert.equal(drink.calories,80);assert.equal(saved.water,before.water);assert.deepEqual(saved.meals,before.meals);assert.equal(saved.complete,false);await click({action:'nav',view:'today',panel:'training'});assert.match(element('#app').innerHTML,/Gatorade/);assert.match(element('#app').innerHTML,/Logged through this drink/);await click({action:'edit-drink',id:drink.id});const edit=element('#edit-drink-form');edit.values={...drink,time:'16:00',ounces:'24',calories:'60',protein:'0',carbs:'15',fat:'0'};edit.onsubmit({preventDefault(){}});assert.equal(storage().days[date].drinks.find(x=>x.id===drink.id).time,'16:00');const good=storage();await click({action:'nav',view:'today',panel:'hydration'});element('#drink-entry').values={type:'Water',time:'17:00',ounces:'-1',calories:'0'};element('#drink-entry').onsubmit({preventDefault(){}});assert.deepEqual(storage(),good);await click({action:'delete-drink',id:drink.id});element('#confirm-action').onclick();assert.ok(!storage().days[date].drinks.some(x=>x.id===drink.id));});
test('copying a generated review refreshes it with drinks saved afterward',async()=>{await click({action:'nav',view:'coach',panel:'review'});element('#review-period').value='day';element('#review-date').value=dateKey();await click({action:'generate'});assert.doesNotMatch(element('#app').innerHTML,/Freshly logged drink/);await click({action:'nav',view:'today',panel:'hydration'});const form=element('#drink-entry');form.values={type:'Freshly logged drink',time:'16:45',ounces:'8',calories:'11',protein:'0',carbs:'2',fat:'0'};form.onsubmit({preventDefault(){}});await click({action:'nav',view:'coach',panel:'review'});element('#review-period').value='day';element('#review-date').value=dateKey();await click({action:'copy-prompt'});assert.match(element('#prompt-output').value,/Freshly logged drink/);assert.match(element('#prompt-output').value,/runningLoggedNutrition/);assert.match(element('#prompt-output').value,/totalFluidOz/);});
test('check-in saves whole-number steps without altering logs, rejects invalid counts and supports blank',async()=>{await click({action:'nav',view:'today',panel:'checkin'});assert.match(element('#app').innerHTML,/Steps count/);assert.match(element('#app').innerHTML,/name="steps"/);const previous=structuredClone(storage().days[dateKey()]),submit=value=>element('#checkin').onsubmit({preventDefault(){},target:{values:{steps:value}}});submit('8246');assert.equal(storage().days[dateKey()].steps,8246);assert.deepEqual(storage().days[dateKey()].meals,previous.meals);assert.deepEqual(storage().days[dateKey()].drinks,previous.drinks);assert.equal(storage().days[dateKey()].notes,previous.notes);const saved=storage();for(const value of ['-1','2.5','1000001']){submit(value);assert.deepEqual(storage(),saved);}submit('0');assert.equal(storage().days[dateKey()].steps,0);submit('');assert.equal(storage().days[dateKey()].steps,null);});
test('food prompt tab preserves pasted JSON and generated description while switching',async()=>{await click({action:'meal-import'});const buttons=element('#modal').querySelectorAll('[data-import-step]');element('#meal-json').value='retain response';buttons.find(b=>b.dataset.importStep==='food').onclick();assert.equal(element('#food-prompt-step').hidden,false);assert.equal(element('#meal-import-step').hidden,true);element('#food-prompt-date').value=dateKey();element('#food-prompt-time').value='12:15';element('#food-prompt-description').value='Turkey sandwich, no mayo';element('#copy-food-template').onclick();assert.match(element('#food-prompt-output').value,/Turkey sandwich, no mayo/);assert.match(element('#food-prompt-output').value,/"schemaVersion":1,"meals"/);assert.equal(element('#food-prompt-result').hidden,false);buttons.find(b=>b.dataset.importStep==='import').onclick();assert.equal(element('#food-prompt-step').hidden,true);assert.equal(element('#meal-json').value,'retain response');assert.equal(element('#food-prompt-description').value,'Turkey sandwich, no mayo');});
test('AI response review imports a meal and reusable food without changing prior entries',async()=>{await click({action:'nav',view:'today',panel:'food'});const before=structuredClone(storage()),meal={date:dateKey(),time:'12:15',name:'AI turkey sandwich',portion:'2 slices bread and 4 oz turkey, no mayo',calories:350,protein:32,carbs:40,fat:7};await click({action:'meal-import'});element('#meal-json').value=JSON.stringify({schemaVersion:1,meals:[meal]});element('#preview-meals').onclick();assert.match(element('#meal-import-review').innerHTML,/AI turkey sandwich/);assert.match(element('#meal-import-review').innerHTML,/textarea name="portion-0" rows="4"/);const form=element('#meal-import-form');form.values={destination:'actual',alsoUsual:'on',...Object.fromEntries(Object.entries(meal).map(([k,v])=>[`${k}-0`,String(v)]))};form.onsubmit({preventDefault(){},target:form});const saved=storage();assert.equal(saved.days[dateKey()].meals.length,before.days[dateKey()].meals.length+1);assert.equal(saved.usualFoods.length,before.usualFoods.length+1);assert.equal(saved.days[dateKey()].meals.find(x=>x.name===meal.name).protein,32);assert.deepEqual(saved.days[dateKey()].drinks,before.days[dateKey()].drinks);for(const original of before.days[dateKey()].meals)assert.deepEqual(saved.days[dateKey()].meals.find(x=>x.id===original.id),original);assert.equal(saved.days[dateKey()].complete,false);});
test('visual timeline places the four-hour fuel marker chronologically without changing logged totals',async()=>{const date='2026-09-01';await click({action:'open-day',date});await click({action:'meal-import'});const meals=[{date,time:'08:00',name:'Early meal',portion:'1 bowl',calories:300,protein:20,carbs:40,fat:7},{date,time:'13:30',name:'Later meal',portion:'1 plate',calories:500,protein:40,carbs:60,fat:11}];element('#meal-json').value=JSON.stringify({schemaVersion:1,meals});element('#preview-meals').onclick();const form=element('#meal-import-form');form.values={destination:'actual',...Object.fromEntries(meals.flatMap((meal,i)=>Object.entries(meal).map(([k,v])=>[`${k}-${i}`,String(v)])))};form.onsubmit({preventDefault(){},target:form});const before=structuredClone(storage());await click({action:'nav',view:'today',panel:'training'});const html=element('#app').innerHTML;assert.match(html,/fuel-legend/);assert.match(html,/fuel-event gap/);assert.match(html,/5h 30m/);assert.match(html,/12:00 PM/);assert.ok(html.indexOf('Early meal')<html.indexOf('<h3>Fueling opportunity</h3>'));assert.ok(html.indexOf('<h3>Fueling opportunity</h3>')<html.indexOf('Later meal'));assert.match(html,/Check for an unlogged meal/);assert.match(html,/Logged through this meal/);assert.deepEqual(storage(),before);});
test('timeline shows settings-based calorie and macro checkpoints and preserves diary values',async()=>{const date='2026-09-01';await click({action:'open-day',date});await click({action:'nav',view:'coach',panel:'import'});element('#import-week').value='2026-08-31';const meal={name:'Planned meal',portion:'1 plate',time:'12:00',calories:600,protein:30,carbs:70,fat:20};element('#plan-input').value=JSON.stringify({schemaVersion:1,weekStart:'2026-08-31',days:range('2026-08-31','week').map(date=>({date,meals:[meal]}))});await click({action:'preview-import'});await click({action:'commit-import'});element('#confirm-action').onclick();await click({action:'open-day',date});const before=storage();await click({action:'nav',view:'today',panel:'training'});const html=element('#app').innerHTML;assert.match(html,/Daily fuel goals/);assert.match(html,/fuel-event checkpoint/);assert.match(html,/More → Goals/);assert.match(html,/Daily goal finish/);assert.match(html,/checkpoint-macros/);assert.match(html,/checkpoint-range/);assert.match(html,/within range/);assert.match(html,/±10%/);assert.doesNotMatch(html,/By this planned meal/);assert.match(html,/not a validated optimum or a guarantee of energy levels/);assert.deepEqual(storage(),before);});
test('planned meals show green Logged state from linked food entries and reset when the entry is removed',async()=>{const before=storage();const [date,plan]=Object.entries(before.plans).find(([date,plan])=>plan.meals.some(m=>!(before.days[date]?.meals||[]).some(log=>log.planMealId===m.id)));const index=plan.meals.findIndex(m=>!(before.days[date]?.meals||[]).some(log=>log.planMealId===m.id));await click({action:'nav',view:'plan'});await click({action:'plan-day',date});await click({action:'eat-plan',date,index:String(index)});element('#confirm-action').onclick();let html=element('#app').innerHTML;const button=new RegExp('class="btn meal-logged"[^>]*data-date="'+date+'"[^>]*data-index="'+index+'"');assert.match(html,button);assert.match(html,/> Logged<\/button>/);const count=storage().days[date].meals.length;await click({action:'eat-plan',date,index:String(index)});assert.match(element('#modal').innerHTML,/Log another serving/);assert.equal(storage().days[date].meals.length,count);element('#modal').close();const logged=storage().days[date].meals.find(m=>m.planMealId===plan.meals[index].id);await click({action:'open-day',date});await click({action:'delete-meal',id:logged.id});element('#confirm-action').onclick();await click({action:'show-today-plan'});assert.doesNotMatch(element('#app').innerHTML,button);assert.match(element('#app').innerHTML,/> Log eaten<\/button>/);await click({action:'nav',view:'today'});assert.match(element('#app').innerHTML,/>Timeline<\/button>/);});
test('usual food categories save, filter, sort, edit and survive reopen without changing diary entries',async()=>{await click({action:'nav',view:'foods',panel:'usual'});await click({action:'clear-filter',list:'foods'});const before=structuredClone(storage().days);for(const food of [{name:'AAA breakfast',category:'breakfast',protein:100},{name:'ZZZ snack',category:'snack',protein:300},{name:'MMM lunch',category:'lunch',protein:200}]){await click({action:'new-usual'});assert.match(element('#modal').innerHTML,/name="category"/);element('#meal-form').onsubmit({preventDefault(){},target:{values:{...food,time:'09:00',portion:'1 serving',calories:'500',protein:String(food.protein),carbs:'30',fat:'10',servings:'1'}}});}element('#usual-category').onchange({target:{value:'breakfast'}});assert.match(element('#app').innerHTML,/AAA breakfast/);assert.doesNotMatch(element('#app').innerHTML,/ZZZ snack/);element('#usual-category').onchange({target:{value:'all'}});element('#usual-sort').onchange({target:{value:'protein'}});element('#usual-direction').onchange({target:{value:'desc'}});assert.ok(element('#app').innerHTML.indexOf('ZZZ snack')<element('#app').innerHTML.indexOf('MMM lunch'));const index=storage().usualFoods.findIndex(f=>f.name==='AAA breakfast');await click({action:'edit-library',kind:'usual',index:String(index)});assert.match(element('#modal').innerHTML,/value="breakfast" selected/);element('#meal-form').onsubmit({preventDefault(){},target:{values:{name:'AAA breakfast',category:'dinner',time:'09:00',portion:'1 serving',calories:'500',protein:'100',carbs:'30',fat:'10',servings:'1'}}});assert.equal(storage().usualFoods[index].category,'dinner');assert.deepEqual(storage().days,before);const saved=structuredClone(storage());await import('../app.js?usual-categories-reopen');assert.deepEqual(storage().usualFoods,saved.usualFoods);});

test('Overview Copy writes the selected day stats to clipboard and offers a fallback without changing data',async()=>{const date='2026-09-01';await click({action:'open-day',date});await click({action:'nav',view:'today',panel:'overview'});const html=element('#app').innerHTML;assert.match(html,/data-action="copy-day-stats"/);assert.ok(html.indexOf('data-action="copy-day-stats"')<html.indexOf('data-action="quick-food-dialog"',html.indexOf('data-action="copy-day-stats"')));const before=structuredClone(storage()),old=Object.getOwnPropertyDescriptor(navigator,'clipboard');let copied='';Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async text=>{copied=text;}}});try{await click({action:'copy-day-stats'});assert.match(copied,/stats for 2026-09-01/);assert.match(copied,/progressAgainstDailyGoals/);assert.match(copied,/loggedMeals/);assert.match(copied,/checkIn/);assert.match(copied,/rest of this day/);assert.deepEqual(storage(),before);element('#modal').close();navigator.clipboard.writeText=async()=>{throw Error('Clipboard denied');};await click({action:'copy-day-stats'});assert.match(element('#modal').innerHTML,/Copy your prompt/);assert.match(element('#modal').innerHTML,/copy-fallback/);assert.match(element('#modal').innerHTML,/2026-09-01/);assert.deepEqual(storage(),before);}finally{if(old)Object.defineProperty(navigator,'clipboard',old);else delete navigator.clipboard;}});
